<script setup lang="ts">
import { computed,ref } from 'vue'
import ExploreFrame from './ExploreFrame.vue'
import { useExperience } from './use-experience'
import { farmBatch,farmNeeds,crops,farmAnimals,farmDay,farmPlot,farmSeason,feedFarm,deliverFarm } from './little-farm'
const props=defineProps<{storageKey?:string}>()
const {save,frame,feedback,resetOpen,act,undo,requestReset,reset,hint}=useExperience(props,'little-farm')
const round=computed(()=>save.value.round),tool=ref<'plant'|'water'|'harvest'>('plant'),seed=ref(0)
const rules=['这是温室小农场，四季都能种植。选一种种子，再点空地播种。','每天浇水后，点击“迎接下一天”，作物才会长大；成熟后切换收获工具。','用仓库里的食物照顾动物，完成村里需要的作物订单，且每只动物都吃过，就完成这一轮。先规划各作物需要的天数。']
function handlePlot(index:number){if(!act(()=>farmPlot(round.value,index,tool.value,seed.value)))feedback.value=tool.value==='plant'?'选一块空地播种。':tool.value==='water'?'先播种，未成熟的作物每天浇一次水。':'作物还没成熟，浇水后迎接下一天。';else feedback.value=tool.value==='harvest'?'收获进入仓库啦！可以种下一批。':tool.value==='water'?'水浇好了，明天会长大一点。':'种子种下了，记得给它浇水。'}
function day(){const growing=round.value.plots.filter(plot=>plot.crop>=0 && plot.growth<crops[plot.crop].days),dry=growing.filter(plot=>!plot.watered).length;act(()=>farmDay(round.value));feedback.value=dry?`新的一天来了。${dry} 块地昨天没有浇水，所以没有生长；今天记得先浇水。`:'新的一天来了，浇过水的作物长大了，看看哪些已经成熟。'}
function batch(tool:'water'|'harvest'){const total=act(()=>farmBatch(round.value,tool));feedback.value=total?`${total} 块地${tool==='water'?'浇好了水':'已收获到仓库'}。`:'暂时没有需要处理的作物。'}
function feed(index:number){if(act(()=>feedFarm(round.value,index)))feedback.value=farmAnimals[index].name+'吃饱了，谢谢你的照顾。';else feedback.value='已经照顾过，或仓库暂时缺少它喜欢的食物。'}
</script>
<template>
  <ExploreFrame v-bind="frame" :progress="`第 ${round.day} 天 · 收获 ${round.harvested} / ${round.goal}`" :rules="rules" @difficulty="requestReset" @undo="undo" @restart="requestReset()" @reset="reset" @cancel="resetOpen=false" @hint="hint('先给每块种了作物的地浇水，再迎接下一天。先看看订单需要哪些作物。胡萝卜、小麦、草莓要两天，番茄、玉米要三天，南瓜要四天。')">
    <div class="farm-landscape"><span class="farm-sun">☀</span><span class="farm-house">🏡</span><div><small>温室小农场</small><h2>{{ farmSeason(round.day) }}的第 {{ round.day }} 天</h2><p>播下一颗种子，看看每天的变化。</p></div></div>
    <div class="explore-toolbar farm-tools"><button :class="{selected:tool==='plant'}" @click="tool='plant'">🌱 播种</button><button :class="{selected:tool==='water'}" @click="tool='water'">💧 浇水</button><button :class="{selected:tool==='harvest'}" @click="tool='harvest'">🧺 收获</button><select v-model.number="seed" aria-label="选择种子"><option v-for="(crop,index) in crops" :key="crop.id" :value="index">{{ crop.name }} · {{ crop.days }} 天</option></select></div>
    <div class="farm-plots"><button v-for="(plot,index) in round.plots" :key="index" :data-plot="index" :aria-label="`农田 ${index+1}`" :disabled="round.finished" :class="{watered:plot.watered,ready:plot.crop>=0 && plot.growth>=crops[plot.crop].days}" @click="handlePlot(index)"><span>{{ plot.crop<0?'＋':plot.growth>=crops[plot.crop].days?crops[plot.crop].icon:plot.growth?'🌿':'🌱' }}</span><strong>{{ plot.crop<0?'空地':crops[plot.crop].name }}</strong><small>{{ plot.crop<0?'点这里播种':plot.growth>=crops[plot.crop].days?'成熟啦！':`${plot.growth} / ${crops[plot.crop].days} 天 · ${plot.watered?'已浇水':'等待浇水'}` }}</small></button></div>
    <div class="explore-checklist" aria-label="还需播种计划"><template v-for="(count,index) in farmNeeds(round)" :key="index"><span v-if="count">{{ crops[index].name }}还需播种 {{ count }} 份</span></template></div><div class="explore-toolbar"><button :disabled="round.finished" @click="batch('water')">给未浇水作物浇水</button><button :disabled="round.finished" @click="batch('harvest')">收获所有成熟作物</button></div><div class="farm-next"><button :disabled="round.finished" class="explore-primary" @click="day">迎接下一天 <UIcon name="i-lucide-sun" /></button></div>
    <template v-if="round.orders"><h2 class="explore-subheading">村里的作物订单</h2><div class="farm-orders"><div v-for="(count,index) in round.orders" :key="index"><template v-if="count"><span>{{ crops[index].icon }} {{ crops[index].name }} {{ round.delivered?.[index] || 0 }} / {{ count }}</span><button class="explore-secondary" :disabled="round.finished || !round.inventory[index] || (round.delivered?.[index] || 0)>=count" @click="act(()=>deliverFarm(round,index));feedback='作物送到了村里。再看看下一份订单。'">交付一份</button></template></div></div></template><h2 class="explore-subheading">农场小仓库</h2><div class="explore-checklist"><span v-for="(crop,index) in crops" :key="crop.id">{{ crop.icon }} {{ crop.name }} × {{ round.inventory[index] }}</span></div>
    <h2 class="explore-subheading">照顾动物伙伴</h2><div class="explore-cards"><button v-for="(fed,index) in round.fed" :key="index" class="explore-card" :disabled="!!fed || round.finished" :aria-label="`喂${farmAnimals[index].name}`" @click="feed(index)"><span>{{ farmAnimals[index].icon }}</span><strong>{{ farmAnimals[index].name }}</strong><small>{{ fed?'吃饱啦 ✓':'喜欢 '+crops[farmAnimals[index].food].name }}</small></button></div>
  </ExploreFrame>
</template>
<style scoped>
.farm-orders>div:has(span){display:flex;justify-content:space-between;gap:12px;align-items:center;padding:11px 0;border-bottom:1px solid #dbe5d2;font-size:12px;color:#728a64}.farm-orders button{font-size:11px}

.farm-landscape{position:relative;overflow:hidden;padding:28px 25px 35px;background:linear-gradient(#e4f0f7 70%,#d4e4c2 70%);border:1px solid #d8e5d0;border-radius:17px;margin-bottom:21px;min-height:190px}.farm-landscape>div{position:relative;z-index:1;max-width:70%}.farm-landscape small{font-size:11px;color:#78927a}.farm-landscape h2{font-size:24px;font-weight:650;margin:10px 0;color:#5d7958}.farm-landscape p{font-size:12px;color:#86937b;line-height:1.9}.farm-sun{position:absolute;right:30px;top:20px;font-size:39px;color:#d4b16b}.farm-house{position:absolute;right:45px;bottom:10px;font-size:68px}.farm-plots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.farm-plots button{display:flex;align-items:center;flex-direction:column;justify-content:center;gap:9px;min-height:145px;border:2px solid #d5bda0;border-bottom-width:7px;background:repeating-linear-gradient(0deg,#e4cfb3 0,#e4cfb3 13px,#dfc6a7 13px,#dfc6a7 15px);border-radius:15px;color:#977f60}.farm-plots button.watered{background:#d5ddd0;border-color:#b6c5b1}.farm-plots button.ready{background:#e5e9c4;border-color:#c0ca98}.farm-plots button>span{font-size:35px}.farm-plots strong{font-size:13px;font-weight:650}.farm-plots small{font-size:10px}.farm-next{display:flex;justify-content:center;margin:23px 0}.farm-tools{margin-bottom:17px}@media(max-width:560px){.farm-landscape{padding:24px 18px;min-height:170px}.farm-landscape h2{font-size:21px}.farm-house{font-size:54px;right:12px}.farm-landscape p{font-size:11px}.farm-plots{gap:10px}.farm-plots button{min-height:136px}.farm-plots small{font-size:9px}}
</style>
